using System;using System.Collections.Generic;using ModStatistik;
class HudHoldTests{static void Need(bool v){if(!v)throw new Exception("HUD hold check failed");}static int Main(){try{var done=new BloodmoonNight(7,new Dictionary<string,long>{{"Player",24}});long v;Need(BloodmoonHudDisplay.TryValue(null,done,100,100,"Player",out v)&&v==24);Need(BloodmoonHudDisplay.TryValue(null,done,100,159.99f,"Player",out v)&&v==24);Need(!BloodmoonHudDisplay.TryValue(null,done,100,160,"Player",out v));Need(!BloodmoonHudDisplay.TryValue(null,done,100,99,"Player",out v));Need(!BloodmoonHudDisplay.TryValue(null,null,100,101,"Player",out v));var live=new BloodmoonNight(14,new Dictionary<string,long>{{"Player",3}});Need(BloodmoonHudDisplay.TryValue(live,done,100,170,"Player",out v)&&v==3);Need(!BloodmoonHudDisplay.TryValue(null,done,100,101,"Other",out v));Console.WriteLine("PASS: final value, 60-second boundary, hiding, reset and new night.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}
